public class WrapperDeepDive {
    public static void main(String[] args) {
        // 1. Identity vs Equality & Caching
        Integer a = 127;
        Integer b = 127;
        System.out.println("127 == 127: " + (a == b)); // true (cached)

        Integer c = 128;
        Integer d = 128;
        System.out.println("128 == 128: " + (c == d)); // false (not cached, separate heap objects)
        System.out.println("128.equals(128): " + c.equals(d)); // true (value comparison)

        // 2. Silent NPE Trap
        Integer nullableCount = null;
        try {
            // Implicit unboxing triggers nullableCount.intValue()
            boolean isEven = (nullableCount % 2 == 0);
        } catch (NullPointerException e) {
            System.err.println("NPE triggered via implicit unboxing on a null wrapper!");
        }

        // 3. Performance Degradation (Autoboxing in loops)
        long startTime = System.nanoTime();
        Long sum = 0L; // Wrapper!
        for (int i = 0; i < 1_000_000; i++) {
            sum += i; // Unboxes sum, adds i, boxes result back to a new Long object!
        }
        long duration = System.nanoTime() - startTime;
        System.out.printf("Wrapper loop took: %,d ns%n", duration);
    }
}
